import { useState, useEffect, useCallback, useRef } from "react";

// Local-storage backed replacement for the artifact-only window.storage API,
// so this component works as a normal standalone web app.
const storage = {
  async get(key) {
    const v = localStorage.getItem(key);
    return v !== null ? { key, value: v } : null;
  },
  async set(key, value) {
    localStorage.setItem(key, value);
    return { key, value };
  },
  async delete(key) {
    localStorage.removeItem(key);
    return { key, deleted: true };
  },
  async list(prefix) {
    const keys = Object.keys(localStorage).filter((k) => !prefix || k.startsWith(prefix));
    return { keys };
  },
};

const LOGO_SRC = "data:image/png;base64,";

const PLOT_OPTIONS = [
  "דדי צפון",
  "דדי דרום",
  "חייקין צפון",
  "חייקין דרום",
  "דבי צפון",
  "דבי דרום",
  "יעקב",
];

const HE_DAYS = ["ראשון", "שני", "שלישי", "רביעי", "חמישי", "שישי", "שבת"];
const HE_MONTHS = [
  "ינואר", "פברואר", "מרץ", "אפריל", "מאי", "יוני",
  "יולי", "אוגוסט", "ספטמבר", "אוקטובר", "נובמבר", "דצמבר",
];

function fmtDateKey(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(
    d.getDate()
  ).padStart(2, "0")}`;
}
function parseDateKey(key) {
  const [y, m, d] = key.split("-").map(Number);
  return new Date(y, m - 1, d);
}
function fmtDateLabel(d) {
  return `יום ${HE_DAYS[d.getDay()]}, ${d.getDate()} ב${HE_MONTHS[d.getMonth()]} ${d.getFullYear()}`;
}
function fmtDateShort(d) {
  return `${d.getDate()}/${d.getMonth() + 1}/${d.getFullYear()}`;
}
function isSameDay(a, b) {
  return fmtDateKey(a) === fmtDateKey(b);
}
function calcWorkHours(start, end) {
  if (!start || !end) return null;
  const [sh, sm] = start.split(":").map(Number);
  const [eh, em] = end.split(":").map(Number);
  if ([sh, sm, eh, em].some((n) => Number.isNaN(n))) return null;
  let mins = eh * 60 + em - (sh * 60 + sm);
  if (mins < 0) mins += 24 * 60;
  return mins / 60;
}
function uid() {
  return Math.random().toString(36).slice(2, 10);
}

function compressImageFile(file, maxDim = 1280, quality = 0.7) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(reader.error);
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("שגיאה בטעינת התמונה"));
      img.onload = () => {
        let { width, height } = img;
        if (width > maxDim || height > maxDim) {
          if (width >= height) {
            height = Math.round((height * maxDim) / width);
            width = maxDim;
          } else {
            width = Math.round((width * maxDim) / height);
            height = maxDim;
          }
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        canvas.getContext("2d").drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

const emptyLog = () => ({
  ownWorkers: 0,
  subcontractors: [],
  workStart: "",
  workEnd: "",
  tasks: [],
  irrigationNotes: "",
  generalNotes: "",
  generalPhotos: [],
});

function buildDayReportText(farmName, currentDate, log, totalWorkers) {
  const subject = `יומן עבודה - ${farmName} - ${fmtDateShort(currentDate)}`;
  const lines = [];
  lines.push(`יומן עבודה יומי - ${farmName}`);
  lines.push(fmtDateLabel(currentDate));
  lines.push("");
  lines.push("נוכחות עובדים:");
  lines.push(`עובדי משק: ${log.ownWorkers || 0}`);
  (log.subcontractors || []).forEach((s) => {
    lines.push(`${s.name || "קבלן ללא שם"}: ${s.count || 0}`);
  });
  lines.push(`סה"כ עובדים: ${totalWorkers}`);
  lines.push("");
  lines.push(`שעות עבודה: ${log.workStart || "-"} עד ${log.workEnd || "-"}`);
  lines.push("");
  if ((log.tasks || []).length) {
    lines.push("משימות שבוצעו:");
    log.tasks.forEach((t) => {
      lines.push(`- ${t.description || "(ללא תיאור)"} | חלקה: ${t.plot || "-"} | מנהרה: ${t.tunnel || "-"}`);
      if (t.notes && t.notes.trim()) {
        lines.push(`  הערות: ${t.notes.trim()}`);
      }
    });
    lines.push("");
  }
  if (log.irrigationNotes && log.irrigationNotes.trim()) {
    lines.push("הערות השקייה:");
    lines.push(log.irrigationNotes.trim());
    lines.push("");
  }
  if ((log.generalNotes && log.generalNotes.trim()) || (log.generalPhotos || []).length) {
    lines.push("הערות כלליות:");
    if (log.generalNotes && log.generalNotes.trim()) lines.push(log.generalNotes.trim());
    if ((log.generalPhotos || []).length) {
      lines.push(`(${log.generalPhotos.length} תמונות מצורפות באפליקציה)`);
    }
  }
  return { subject, body: lines.join("\n") };
}

function buildDayMailto(farmName, currentDate, log, totalWorkers) {
  const { subject, body } = buildDayReportText(farmName, currentDate, log, totalWorkers);
  return `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

function dataUrlToFile(dataUrl, filename) {
  const [header, base64] = dataUrl.split(",");
  const mimeMatch = header.match(/data:(.*);base64/);
  const mime = mimeMatch ? mimeMatch[1] : "image/jpeg";
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new File([bytes], filename, { type: mime });
}

function canShareWithPhotos() {
  return typeof navigator !== "undefined" && !!navigator.share && !!navigator.canShare;
}

async function shareWithPhotos(subject, body, photos) {
  const files = photos.map((src, i) => dataUrlToFile(src, `תמונה-${i + 1}.jpg`));
  if (!navigator.canShare({ files })) return false;
  await navigator.share({ title: subject, text: body, files });
  return true;
}

async function elementToPdfFile(element, filename) {
  const [{ jsPDF }, { default: html2canvas }] = await Promise.all([
    import("jspdf"),
    import("html2canvas"),
  ]);
  const canvas = await html2canvas(element, {
    scale: 2,
    backgroundColor: "#ffffff",
    onclone: (clonedDoc) => {
      clonedDoc.querySelectorAll(".no-print").forEach((el) => {
        el.style.display = "none";
      });
    },
  });
  const imgData = canvas.toDataURL("image/jpeg", 0.92);
  const pdf = new jsPDF({ unit: "pt", format: "a4" });
  const pageWidth = pdf.internal.pageSize.getWidth();
  const pageHeight = pdf.internal.pageSize.getHeight();
  const imgWidth = pageWidth;
  const imgHeight = (canvas.height * imgWidth) / canvas.width;
  let heightLeft = imgHeight;
  let position = 0;
  pdf.addImage(imgData, "JPEG", 0, position, imgWidth, imgHeight);
  heightLeft -= pageHeight;
  while (heightLeft > 0) {
    position = heightLeft - imgHeight;
    pdf.addPage();
    pdf.addImage(imgData, "JPEG", 0, position, imgWidth, imgHeight);
    heightLeft -= pageHeight;
  }
  const blob = pdf.output("blob");
  return new File([blob], filename, { type: "application/pdf" });
}

function downloadFile(file) {
  const url = URL.createObjectURL(file);
  const a = document.createElement("a");
  a.href = url;
  a.download = file.name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

function copyToClipboard(text) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    return navigator.clipboard.writeText(text);
  }
  return new Promise((resolve, reject) => {
    try {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      const ok = document.execCommand("copy");
      document.body.removeChild(ta);
      ok ? resolve() : reject(new Error("copy failed"));
    } catch (e) {
      reject(e);
    }
  });
}

export default function FarmDailyLog() {
  const [farmName, setFarmName] = useState("משק תורג'מן");
  const [editingName, setEditingName] = useState(false);
  const [activeTab, setActiveTab] = useState("log"); // 'log' | 'reports'
  const [currentDate, setCurrentDate] = useState(new Date());
  const [log, setLog] = useState(emptyLog());
  const [loading, setLoading] = useState(true);
  const [saveStatus, setSaveStatus] = useState("idle"); // idle | saving | saved | error
  const saveTimer = useRef(null);

  const dateKey = fmtDateKey(currentDate);
  const today = new Date();
  const isToday = isSameDay(currentDate, today);

  // load farm name once
  useEffect(() => {
    (async () => {
      try {
        const res = await storage.get("farm-name");
        if (res && res.value) setFarmName(res.value);
      } catch (e) {}
    })();
  }, []);

  // load log for current date
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    (async () => {
      try {
        const res = await storage.get(`log:${dateKey}`);
        if (!cancelled) {
          setLog(res && res.value ? JSON.parse(res.value) : emptyLog());
          setLoading(false);
          setSaveStatus("idle");
        }
      } catch (e) {
        if (!cancelled) {
          setLog(emptyLog());
          setLoading(false);
          setSaveStatus("idle");
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [dateKey]);

  const persist = useCallback(
    (nextLog) => {
      if (saveTimer.current) clearTimeout(saveTimer.current);
      setSaveStatus("saving");
      saveTimer.current = setTimeout(async () => {
        try {
          const result = await storage.set(
            `log:${dateKey}`,
            JSON.stringify(nextLog)
          );
          setSaveStatus(result ? "saved" : "error");
        } catch (e) {
          setSaveStatus("error");
        }
      }, 500);
    },
    [dateKey]
  );

  function updateLog(patch) {
    const next = { ...log, ...patch };
    setLog(next);
    persist(next);
  }

  async function saveNow() {
    if (saveTimer.current) clearTimeout(saveTimer.current);
    setSaveStatus("saving");
    try {
      const result = await storage.set(`log:${dateKey}`, JSON.stringify(log));
      setSaveStatus(result ? "saved" : "error");
    } catch (e) {
      setSaveStatus("error");
    }
  }

  function saveFarmName(name) {
    const clean = name.trim() || "משק תורג'מן";
    setFarmName(clean);
    storage.set("farm-name", clean).catch(() => {});
  }

  function shiftDay(delta) {
    const d = new Date(currentDate);
    d.setDate(d.getDate() + delta);
    setCurrentDate(d);
  }

  // ---- subcontractors ----
  function addSubcontractor() {
    updateLog({
      subcontractors: [...log.subcontractors, { id: uid(), name: "", count: 0 }],
    });
  }
  function updateSubcontractor(id, patch) {
    updateLog({
      subcontractors: log.subcontractors.map((s) =>
        s.id === id ? { ...s, ...patch } : s
      ),
    });
  }
  function removeSubcontractor(id) {
    updateLog({ subcontractors: log.subcontractors.filter((s) => s.id !== id) });
  }

  // ---- tasks ----
  function addTask() {
    updateLog({
      tasks: [...log.tasks, { id: uid(), description: "", plot: "", tunnel: "", notes: "" }],
    });
  }
  function updateTask(id, patch) {
    updateLog({
      tasks: log.tasks.map((t) => (t.id === id ? { ...t, ...patch } : t)),
    });
  }
  function removeTask(id) {
    updateLog({ tasks: log.tasks.filter((t) => t.id !== id) });
  }

  const subWorkersTotal = log.subcontractors.reduce(
    (sum, s) => sum + (Number(s.count) || 0),
    0
  );
  const totalWorkers = (Number(log.ownWorkers) || 0) + subWorkersTotal;

  return (
    <div style={styles.page}>
      <GlobalStyle />
      <div className="farm-scope" style={styles.scope}>
        <Header
          farmName={farmName}
          editingName={editingName}
          setEditingName={setEditingName}
          setFarmName={setFarmName}
          saveFarmName={saveFarmName}
        />

        <div className="no-print" style={styles.tabBar}>
          <button
            style={{
              ...styles.tabBtn,
              ...(activeTab === "log" ? styles.tabBtnActive : {}),
            }}
            onClick={() => setActiveTab("log")}
          >
            יומן יומי
          </button>
          <button
            style={{
              ...styles.tabBtn,
              ...(activeTab === "reports" ? styles.tabBtnActive : {}),
            }}
            onClick={() => setActiveTab("reports")}
          >
            דוחות
          </button>
        </div>

        {activeTab === "log" ? (
          <DailyLogView
            currentDate={currentDate}
            shiftDay={shiftDay}
            isToday={isToday}
            setCurrentDate={setCurrentDate}
            loading={loading}
            log={log}
            updateLog={updateLog}
            addSubcontractor={addSubcontractor}
            updateSubcontractor={updateSubcontractor}
            removeSubcontractor={removeSubcontractor}
            addTask={addTask}
            updateTask={updateTask}
            removeTask={removeTask}
            subWorkersTotal={subWorkersTotal}
            totalWorkers={totalWorkers}
            saveStatus={saveStatus}
            farmName={farmName}
            saveNow={saveNow}
          />
        ) : (
          <ReportsView farmName={farmName} />
        )}
        <div style={{ height: 24 }} />
      </div>
    </div>
  );
}

function Header({ farmName }) {
  return (
    <div className="no-print" style={styles.sign}>
      <img src={LOGO_SRC} alt={farmName} style={styles.logoImg} />
    </div>
  );
}

function DailyLogView({
  currentDate,
  shiftDay,
  isToday,
  setCurrentDate,
  loading,
  log,
  updateLog,
  addSubcontractor,
  updateSubcontractor,
  removeSubcontractor,
  addTask,
  updateTask,
  removeTask,
  subWorkersTotal,
  totalWorkers,
  saveStatus,
  farmName,
  saveNow,
}) {
  const [copyMsg, setCopyMsg] = useState("");
  return (
    <>
      {/* Date navigator */}
      <div className="no-print" style={styles.dateBar}>
        <button style={styles.navBtn} onClick={() => shiftDay(-1)} aria-label="יום קודם">
          ›
        </button>
        <div style={styles.dateCenter}>
          <div style={styles.dateLabel}>{fmtDateLabel(currentDate)}</div>
          <div style={styles.dateSubRow}>
            <input
              type="date"
              value={fmtDateKey(currentDate)}
              onChange={(e) => {
                if (e.target.value) {
                  const [y, m, d] = e.target.value.split("-").map(Number);
                  setCurrentDate(new Date(y, m - 1, d));
                }
              }}
              style={styles.dateInput}
            />
            {!isToday && (
              <button style={styles.todayLink} onClick={() => setCurrentDate(new Date())}>
                חזרה להיום
              </button>
            )}
          </div>
        </div>
        <button style={styles.navBtn} onClick={() => shiftDay(1)} aria-label="יום הבא">
          ‹
        </button>
      </div>

      <div style={styles.saveRow}>
        <button className="no-print" style={styles.saveBtn} onClick={saveNow}>
          💾 שמור
        </button>
        <div style={styles.saveIndicator}>
          {saveStatus === "saving" && "שומר…"}
          {saveStatus === "saved" && "✓ נשמר"}
          {saveStatus === "error" && "⚠ שמירה נכשלה"}
        </div>
      </div>

      {!loading && (
        <div className="no-print" style={styles.emailActionsWrap}>
          <button
            style={styles.copyBtn}
            onClick={() => {
              const { subject, body } = buildDayReportText(
                farmName,
                currentDate,
                log,
                totalWorkers
              );
              copyToClipboard(`${subject}\n\n${body}`)
                .then(() => {
                  setCopyMsg("✓ הועתק! עכשיו פתח את המייל והדבק (Paste)");
                  setTimeout(() => setCopyMsg(""), 4000);
                })
                .catch(() => {
                  setCopyMsg("⚠ ההעתקה נכשלה, נסה שוב");
                  setTimeout(() => setCopyMsg(""), 4000);
                });
            }}
          >
            📋 העתק את יומן היום למייל
          </button>
          {(log.generalPhotos || []).length > 0 && canShareWithPhotos() && (
            <button
              style={styles.copyBtn}
              onClick={async () => {
                const { subject, body } = buildDayReportText(
                  farmName,
                  currentDate,
                  log,
                  totalWorkers
                );
                try {
                  const shared = await shareWithPhotos(subject, body, log.generalPhotos);
                  if (!shared) {
                    setCopyMsg("שיתוף עם תמונות לא נתמך במכשיר זה");
                    setTimeout(() => setCopyMsg(""), 4000);
                  }
                } catch (err) {
                  if (err && err.name !== "AbortError") {
                    setCopyMsg("⚠ השיתוף נכשל, נסה שוב");
                    setTimeout(() => setCopyMsg(""), 4000);
                  }
                }
              }}
            >
              📎 שתף כולל תמונות (למייל / וואטסאפ)
            </button>
          )}
          <a
            style={styles.mailtoLink}
            href={buildDayMailto(farmName, currentDate, log, totalWorkers)}
          >
            או נסה לפתוח ישירות באפליקציית המייל
          </a>
          {copyMsg && <div style={styles.copyMsg}>{copyMsg}</div>}
        </div>
      )}

      {loading ? (
        <div style={styles.emptyState}>טוען…</div>
      ) : (
        <div style={styles.cardsWrap}>
          {/* Workers */}
          <Card title="נוכחות עובדים" icon="👷" accent="#D6402C">
            <div className="grid-2">
              <Field label="עובדי המשק שהגיעו היום">
                <NumberStepper
                  value={log.ownWorkers}
                  onChange={(v) => updateLog({ ownWorkers: v })}
                />
              </Field>
              <Field label="סה״כ עובדים היום">
                <div style={styles.totalBadge}>{totalWorkers}</div>
              </Field>
            </div>

            <div style={styles.subDivider}>קבלני משנה</div>
            {log.subcontractors.length === 0 && (
              <div style={styles.mutedNote}>אין קבלני משנה רשומים ליום זה</div>
            )}
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {log.subcontractors.map((s) => (
                <div key={s.id} style={styles.subRow}>
                  <input
                    style={styles.subNameInput}
                    placeholder="שם קבלן המשנה"
                    value={s.name}
                    onChange={(e) =>
                      updateSubcontractor(s.id, { name: e.target.value })
                    }
                  />
                  <div style={styles.subCountWrap}>
                    <NumberStepper
                      compact
                      value={s.count}
                      onChange={(v) => updateSubcontractor(s.id, { count: v })}
                    />
                  </div>
                  <button
                    style={styles.iconDelete}
                    onClick={() => removeSubcontractor(s.id)}
                    aria-label="מחק קבלן משנה"
                  >
                    ✕
                  </button>
                </div>
              ))}
            </div>
            <button style={styles.addRowBtn} onClick={addSubcontractor}>
              + הוסף קבלן משנה
            </button>
            {subWorkersTotal > 0 && (
              <div style={styles.mutedNote}>
                סה״כ עובדי קבלנים: {subWorkersTotal}
              </div>
            )}
          </Card>

          {/* Work hours */}
          <Card title="שעות עבודה" icon="⏱" accent="#B9770E">
            <div className="grid-2">
              <Field label="משעה">
                <input
                  type="time"
                  style={styles.input}
                  value={log.workStart}
                  onChange={(e) => updateLog({ workStart: e.target.value })}
                />
              </Field>
              <Field label="עד שעה">
                <input
                  type="time"
                  style={styles.input}
                  value={log.workEnd}
                  onChange={(e) => updateLog({ workEnd: e.target.value })}
                />
              </Field>
            </div>
          </Card>

          {/* Tasks */}
          <Card title="משימות שבוצעו" icon="🍉" accent="#3C7A43">
            {log.tasks.length === 0 && (
              <div style={styles.mutedNote}>לא נרשמו משימות ליום זה</div>
            )}
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {log.tasks.map((t) => (
                <div key={t.id} style={styles.taskRow}>
                  <input
                    style={styles.taskDescInput}
                    placeholder="תיאור המשימה"
                    value={t.description}
                    onChange={(e) => updateTask(t.id, { description: e.target.value })}
                  />
                  <div style={styles.taskMetaRow}>
                    <select
                      style={styles.taskMetaInput}
                      value={t.plot}
                      onChange={(e) => updateTask(t.id, { plot: e.target.value })}
                    >
                      <option value="">חלקה</option>
                      {PLOT_OPTIONS.map((p) => (
                        <option key={p} value={p}>
                          {p}
                        </option>
                      ))}
                    </select>
                    <input
                      style={styles.taskMetaInput}
                      placeholder="מס׳ מנהרה"
                      value={t.tunnel}
                      onChange={(e) => updateTask(t.id, { tunnel: e.target.value })}
                    />
                    <button
                      style={styles.iconDelete}
                      onClick={() => removeTask(t.id)}
                      aria-label="מחק משימה"
                    >
                      ✕
                    </button>
                  </div>
                  <input
                    style={styles.taskNotesInput}
                    placeholder="הערות"
                    value={t.notes || ""}
                    onChange={(e) => updateTask(t.id, { notes: e.target.value })}
                  />
                </div>
              ))}
            </div>
            <button style={styles.addRowBtn} onClick={addTask}>
              + הוסף משימה
            </button>
          </Card>

          {/* Irrigation notes */}
          <Card title="הערות השקייה" icon="💧" accent="#1F7D8C">
            <textarea
              style={styles.textarea}
              rows={3}
              placeholder="לדוגמה: השקיה בחלקה 3 הופסקה בשל תקלה בברז..."
              value={log.irrigationNotes}
              onChange={(e) => updateLog({ irrigationNotes: e.target.value })}
            />
          </Card>

          {/* General notes */}
          <Card title="הערות כלליות" icon="📝" accent="#5A5A54">
            <textarea
              style={styles.textarea}
              rows={3}
              placeholder="כל דבר נוסף שכדאי לתעד..."
              value={log.generalNotes}
              onChange={(e) => updateLog({ generalNotes: e.target.value })}
            />
            {(log.generalPhotos || []).length > 0 && (
              <div style={styles.photoGrid}>
                {log.generalPhotos.map((src, i) => (
                  <div key={i} style={styles.photoThumbWrap}>
                    <img src={src} alt={`תמונה ${i + 1}`} style={styles.photoThumb} />
                    <button
                      style={styles.photoRemoveBtn}
                      onClick={() =>
                        updateLog({
                          generalPhotos: log.generalPhotos.filter((_, idx) => idx !== i),
                        })
                      }
                      aria-label="הסר תמונה"
                    >
                      ✕
                    </button>
                  </div>
                ))}
              </div>
            )}
            <label style={styles.addPhotoBtn}>
              + הוסף תמונה
              <input
                type="file"
                accept="image/*"
                capture="environment"
                style={{ display: "none" }}
                onChange={async (e) => {
                  const files = Array.from(e.target.files || []);
                  e.target.value = "";
                  if (!files.length) return;
                  try {
                    const compressed = await Promise.all(files.map((f) => compressImageFile(f)));
                    updateLog({ generalPhotos: [...(log.generalPhotos || []), ...compressed] });
                  } catch (err) {
                    alert("שגיאה בהוספת התמונה");
                  }
                }}
              />
            </label>
          </Card>
        </div>
      )}
    </>
  );
}

function Card({ title, icon, accent, children }) {
  return (
    <div style={styles.card}>
      <div style={styles.cardHeader}>
        <span style={{ fontSize: 18 }}>{icon}</span>
        <span style={{ ...styles.cardTitle, color: accent }}>{title}</span>
      </div>
      <div style={{ ...styles.cardAccent, background: accent }} />
      {children}
    </div>
  );
}

function Field({ label, children }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
      <label style={styles.fieldLabel}>{label}</label>
      {children}
    </div>
  );
}

function NumberStepper({ value, onChange, compact }) {
  const v = Number(value) || 0;
  return (
    <div style={{ ...styles.stepper, ...(compact ? styles.stepperCompact : {}) }}>
      <button
        style={styles.stepperBtn}
        onClick={() => onChange(Math.max(0, v - 1))}
        aria-label="הפחת"
      >
        −
      </button>
      <input
        type="number"
        min={0}
        style={styles.stepperInput}
        value={v}
        onChange={(e) => onChange(Math.max(0, Number(e.target.value) || 0))}
      />
      <button style={styles.stepperBtn} onClick={() => onChange(v + 1)} aria-label="הוסף">
        +
      </button>
    </div>
  );
}

function downloadBlob(content, filename, mime) {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function csvCell(value) {
  return `"${String(value ?? "").replace(/"/g, '""')}"`;
}

function buildReportCSV(report, farmName, rangeFrom, rangeTo) {
  const rows = [];
  rows.push([`דוח מסכם - ${farmName}`]);
  rows.push([`טווח תאריכים: ${rangeFrom} עד ${rangeTo}`]);
  rows.push([]);
  rows.push(["ימים מתועדים", report.daysCount]);
  rows.push(["סה\"כ ימי עבודה - עובדי משק", report.totalOwn]);
  rows.push(["סה\"כ ימי עבודה - קבלנים", report.totalSub]);
  rows.push(["ממוצע עובדים ליום", report.avgPerDay.toFixed(1)]);
  rows.push([]);
  if (report.days.length) {
    rows.push([
      "תאריך",
      "עובדי משק",
      "קבלני משנה",
      "סה\"כ עובדים",
      "שעות עבודה",
      "סה\"כ שעות",
    ]);
    report.days.forEach((day) => {
      const ownWorkers = Number(day.ownWorkers) || 0;
      const subs = (day.subcontractors || []).filter((s) => (Number(s.count) || 0) > 0);
      const subTotal = subs.reduce((sum, s) => sum + (Number(s.count) || 0), 0);
      const hours = calcWorkHours(day.workStart, day.workEnd);
      rows.push([
        fmtDateShort(parseDateKey(day.date)),
        ownWorkers,
        subs.length
          ? subs.map((s) => `${s.name || "קבלן ללא שם"} (${s.count || 0})`).join("; ")
          : "-",
        ownWorkers + subTotal,
        `${day.workStart || "-"} עד ${day.workEnd || "-"}`,
        hours !== null ? hours.toFixed(1) : "-",
      ]);
    });
    rows.push([]);
  }
  if (Object.keys(report.subTotals).length) {
    rows.push(["קבלני משנה", "מספר ימים", "סה\"כ עובדים"]);
    Object.entries(report.subTotals).forEach(([name, count]) =>
      rows.push([name, report.subDaysCounts[name] || 0, count])
    );
    rows.push([]);
  }
  if (report.taskList.length) {
    rows.push(["תאריך", "תיאור משימה", "חלקה", "מנהרה", "הערות"]);
    report.taskList.forEach((t) =>
      rows.push([fmtDateShort(parseDateKey(t.date)), t.description, t.plot, t.tunnel, t.notes])
    );
    rows.push([]);
  }
  if (report.irrigationEntries.length) {
    rows.push(["הערות השקייה"]);
    report.irrigationEntries.forEach((e) =>
      rows.push([fmtDateShort(parseDateKey(e.date)), e.text])
    );
    rows.push([]);
  }
  if (report.generalEntries.length) {
    rows.push(["תאריך", "הערות כלליות", "מספר תמונות מצורפות"]);
    report.generalEntries.forEach((e) =>
      rows.push([fmtDateShort(parseDateKey(e.date)), e.text, (e.photos || []).length])
    );
  }
  const csv = rows.map((r) => r.map(csvCell).join(",")).join("\r\n");
  return "\uFEFF" + csv;
}

function buildReportText(report, farmName, rangeFrom, rangeTo) {
  const subject = `דוח מסכם - ${farmName} - ${rangeFrom} עד ${rangeTo}`;
  const lines = [];
  lines.push(`דוח מסכם - ${farmName}`);
  lines.push(`טווח תאריכים: ${rangeFrom} עד ${rangeTo}`);
  lines.push("");
  lines.push(`ימים מתועדים: ${report.daysCount}`);
  lines.push(`סה"כ ימי עבודה - עובדי משק: ${report.totalOwn}`);
  lines.push(`סה"כ ימי עבודה - קבלנים: ${report.totalSub}`);
  lines.push(`ממוצע עובדים ליום: ${report.avgPerDay.toFixed(1)}`);
  lines.push("");
  if (report.days.length) {
    lines.push("נוכחות ושעות עבודה לפי תאריך:");
    report.days.forEach((day) => {
      const ownWorkers = Number(day.ownWorkers) || 0;
      const subs = (day.subcontractors || []).filter((s) => (Number(s.count) || 0) > 0);
      const subTotal = subs.reduce((sum, s) => sum + (Number(s.count) || 0), 0);
      const hours = calcWorkHours(day.workStart, day.workEnd);
      const subsText = subs.length
        ? subs.map((s) => `${s.name || "קבלן ללא שם"} (${s.count || 0})`).join(", ")
        : "-";
      lines.push(
        `${fmtDateShort(parseDateKey(day.date))} - עובדי משק: ${ownWorkers} | קבלנים: ${subsText} | סה"כ עובדים: ${
          ownWorkers + subTotal
        } | שעות: ${day.workStart || "-"} עד ${day.workEnd || "-"} (${
          hours !== null ? hours.toFixed(1) : "-"
        } שעות)`
      );
    });
    lines.push("");
  }
  if (Object.keys(report.subTotals).length) {
    lines.push("קבלני משנה:");
    Object.entries(report.subTotals).forEach(([name, count]) =>
      lines.push(`${name}: ${count} עובדים (${report.subDaysCounts[name] || 0} ימים)`)
    );
    lines.push("");
  }
  if (report.taskList.length) {
    const maxItems = 25;
    lines.push(`משימות שבוצעו (${report.taskList.length}):`);
    report.taskList.slice(0, maxItems).forEach((t) => {
      lines.push(
        `${fmtDateShort(parseDateKey(t.date))} - ${t.description || "(ללא תיאור)"} | חלקה: ${t.plot || "-"} | מנהרה: ${t.tunnel || "-"}${t.notes ? ` | הערות: ${t.notes}` : ""}`
      );
    });
    if (report.taskList.length > maxItems) {
      lines.push(`… ועוד ${report.taskList.length - maxItems} משימות. לפירוט מלא ייצא את הדוח כ-CSV.`);
    }
    lines.push("");
  }
  if (report.irrigationEntries.length) {
    lines.push("הערות השקייה:");
    report.irrigationEntries.forEach((e) =>
      lines.push(`${fmtDateShort(parseDateKey(e.date))}: ${e.text}`)
    );
    lines.push("");
  }
  if (report.generalEntries.length) {
    lines.push("הערות כלליות:");
    report.generalEntries.forEach((e) =>
      lines.push(
        `${fmtDateShort(parseDateKey(e.date))}: ${e.text}${
          e.photos && e.photos.length ? ` (${e.photos.length} תמונות מצורפות באפליקציה)` : ""
        }`
      )
    );
  }
  return { subject, body: lines.join("\n") };
}

function buildReportMailto(report, farmName, rangeFrom, rangeTo) {
  const { subject, body } = buildReportText(report, farmName, rangeFrom, rangeTo);
  return `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

async function exportFullBackup(farmName) {
  const listRes = await storage.list("log:");
  const keys = (listRes && listRes.keys) || [];
  const entries = await Promise.all(
    keys.map(async (k) => {
      try {
        const res = await storage.get(k);
        return [k.replace("log:", ""), res && res.value ? JSON.parse(res.value) : null];
      } catch (e) {
        return [k.replace("log:", ""), null];
      }
    })
  );
  const logs = Object.fromEntries(entries.filter(([, v]) => v));
  const backup = {
    farmName,
    exportedAt: new Date().toISOString(),
    logs,
  };
  downloadBlob(
    JSON.stringify(backup, null, 2),
    `גיבוי-${fmtDateKey(new Date())}.json`,
    "application/json;charset=utf-8;"
  );
}

// ---------------- Reports ----------------

function ReportsView({ farmName }) {
  const [rangeFrom, setRangeFrom] = useState(() => {
    const d = new Date();
    d.setDate(d.getDate() - 6);
    return fmtDateKey(d);
  });
  const [rangeTo, setRangeTo] = useState(() => fmtDateKey(new Date()));
  const [report, setReport] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [copyMsg, setCopyMsg] = useState("");
  const [pdfBusy, setPdfBusy] = useState(false);
  const printAreaRef = useRef(null);

  async function generateReport() {
    setLoading(true);
    setError("");
    setReport(null);
    try {
      const listRes = await storage.list("log:");
      const keys = (listRes && listRes.keys) || [];
      const fromD = rangeFrom;
      const toD = rangeTo;
      const inRange = keys.filter((k) => {
        const dk = k.replace("log:", "");
        return dk >= fromD && dk <= toD;
      });
      const entries = await Promise.all(
        inRange.map(async (k) => {
          try {
            const res = await storage.get(k);
            return res && res.value
              ? { date: k.replace("log:", ""), ...JSON.parse(res.value) }
              : null;
          } catch (e) {
            return null;
          }
        })
      );
      const days = entries.filter(Boolean).sort((a, b) => (a.date < b.date ? -1 : 1));

      let totalOwn = 0;
      let totalSub = 0;
      const subTotals = {};
      const subDaysCounts = {};
      const plotCounts = {};
      const tunnelCounts = {};
      const taskList = [];
      const irrigationEntries = [];
      const generalEntries = [];

      days.forEach((day) => {
        totalOwn += Number(day.ownWorkers) || 0;
        const subNamesToday = new Set();
        (day.subcontractors || []).forEach((s) => {
          const c = Number(s.count) || 0;
          totalSub += c;
          const name = s.name.trim() || "קבלן ללא שם";
          subTotals[name] = (subTotals[name] || 0) + c;
          if (c > 0 && !subNamesToday.has(name)) {
            subDaysCounts[name] = (subDaysCounts[name] || 0) + 1;
            subNamesToday.add(name);
          }
        });
        (day.tasks || []).forEach((t) => {
          if (!t.description && !t.plot && !t.tunnel && !t.notes) return;
          taskList.push({ date: day.date, ...t });
          if (t.plot) plotCounts[t.plot] = (plotCounts[t.plot] || 0) + 1;
          if (t.tunnel) tunnelCounts[t.tunnel] = (tunnelCounts[t.tunnel] || 0) + 1;
        });
        if (day.irrigationNotes && day.irrigationNotes.trim()) {
          irrigationEntries.push({ date: day.date, text: day.irrigationNotes });
        }
        if ((day.generalNotes && day.generalNotes.trim()) || (day.generalPhotos || []).length) {
          generalEntries.push({
            date: day.date,
            text: day.generalNotes || "",
            photos: day.generalPhotos || [],
          });
        }
      });

      setReport({
        days,
        daysCount: days.length,
        totalOwn,
        totalSub,
        totalWorkerDays: totalOwn + totalSub,
        avgPerDay: days.length ? (totalOwn + totalSub) / days.length : 0,
        subTotals,
        subDaysCounts,
        plotCounts,
        tunnelCounts,
        taskList,
        irrigationEntries,
        generalEntries,
      });
    } catch (e) {
      setError("אירעה שגיאה בהפקת הדוח, נסה שוב");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div>
      <div className="no-print" style={styles.card}>
        <div style={styles.cardHeader}>
          <span style={{ fontSize: 18 }}>📊</span>
          <span style={{ ...styles.cardTitle, color: "#D6402C" }}>הפקת דוח מסכם</span>
        </div>
        <div style={{ ...styles.cardAccent, background: "#D6402C" }} />
        <div className="grid-2">
          <Field label="מתאריך">
            <input
              type="date"
              style={styles.input}
              value={rangeFrom}
              onChange={(e) => setRangeFrom(e.target.value)}
            />
          </Field>
          <Field label="עד תאריך">
            <input
              type="date"
              style={styles.input}
              value={rangeTo}
              onChange={(e) => setRangeTo(e.target.value)}
            />
          </Field>
        </div>
        <button style={styles.primaryBtn} onClick={generateReport} disabled={loading}>
          {loading ? "מפיק דוח…" : "הפק דוח"}
        </button>
        {error && <div style={styles.errorBanner}>{error}</div>}
        <button
          style={styles.secondaryBtn}
          onClick={() => exportFullBackup(farmName)}
        >
          ⬇ ייצוא גיבוי מלא של כל הנתונים (JSON)
        </button>
      </div>

      {report && (
        <div style={styles.reportPrintArea} ref={printAreaRef}>
          <div style={styles.reportPrintHeader}>
            <img src={LOGO_SRC} alt={farmName} style={styles.reportPrintLogo} />
            <div style={styles.reportPrintTitle}>{farmName} — דוח מסכם</div>
            <div style={styles.reportPrintSub}>
              {rangeFrom} עד {rangeTo} · {report.daysCount} ימים מתועדים
            </div>
          </div>

          <div className="no-print" style={styles.reportActionsRow}>
            <button style={styles.printBtn} onClick={() => window.print()}>
              🖨 הדפס / שמור כ-PDF
            </button>
            <button
              style={styles.csvBtn}
              onClick={() =>
                downloadBlob(
                  buildReportCSV(report, farmName, rangeFrom, rangeTo),
                  `דוח-${rangeFrom}-עד-${rangeTo}.csv`,
                  "text/csv;charset=utf-8;"
                )
              }
            >
              ⬇ ייצוא הדוח לאקסל (CSV)
            </button>
            <button
              style={styles.emailBtn}
              onClick={() => {
                const { subject, body } = buildReportText(
                  report,
                  farmName,
                  rangeFrom,
                  rangeTo
                );
                copyToClipboard(`${subject}\n\n${body}`)
                  .then(() => {
                    setCopyMsg("✓ הועתק! עכשיו פתח את המייל והדבק (Paste)");
                    setTimeout(() => setCopyMsg(""), 4000);
                  })
                  .catch(() => {
                    setCopyMsg("⚠ ההעתקה נכשלה, נסה שוב");
                    setTimeout(() => setCopyMsg(""), 4000);
                  });
              }}
            >
              📋 העתק דוח למייל
            </button>
            {report.generalEntries.some((e) => (e.photos || []).length > 0) &&
              canShareWithPhotos() && (
                <button
                  style={styles.emailBtn}
                  onClick={async () => {
                    const { subject, body } = buildReportText(
                      report,
                      farmName,
                      rangeFrom,
                      rangeTo
                    );
                    const photos = report.generalEntries.flatMap((e) => e.photos || []);
                    try {
                      const shared = await shareWithPhotos(subject, body, photos);
                      if (!shared) {
                        setCopyMsg("שיתוף עם תמונות לא נתמך במכשיר זה");
                        setTimeout(() => setCopyMsg(""), 4000);
                      }
                    } catch (err) {
                      if (err && err.name !== "AbortError") {
                        setCopyMsg("⚠ השיתוף נכשל, נסה שוב");
                        setTimeout(() => setCopyMsg(""), 4000);
                      }
                    }
                  }}
                >
                  📎 שתף כולל תמונות
                </button>
              )}
            <button
              style={styles.emailBtn}
              disabled={pdfBusy}
              onClick={async () => {
                if (!printAreaRef.current) return;
                setPdfBusy(true);
                try {
                  const filename = `דוח-${rangeFrom}-עד-${rangeTo}.pdf`;
                  const file = await elementToPdfFile(printAreaRef.current, filename);
                  if (canShareWithPhotos() && navigator.canShare({ files: [file] })) {
                    await navigator.share({ title: `${farmName} — דוח מסכם`, files: [file] });
                  } else {
                    downloadFile(file);
                  }
                } catch (err) {
                  if (err && err.name !== "AbortError") {
                    setCopyMsg("⚠ יצירת ה-PDF נכשלה, נסה שוב");
                    setTimeout(() => setCopyMsg(""), 4000);
                  }
                } finally {
                  setPdfBusy(false);
                }
              }}
            >
              {pdfBusy ? "מכין PDF…" : "📄 שלח כ-PDF"}
            </button>
          </div>
          {copyMsg && (
            <div className="no-print" style={styles.copyMsg}>
              {copyMsg}
            </div>
          )}
          <a
            className="no-print"
            style={styles.mailtoLink}
            href={buildReportMailto(report, farmName, rangeFrom, rangeTo)}
          >
            או נסה לפתוח ישירות באפליקציית המייל
          </a>

          <div style={styles.reportStatsGrid}>
            <StatBox label="ימים מתועדים" value={report.daysCount} />
            <StatBox label="סה״כ ימי־עבודה, עובדי משק" value={report.totalOwn} />
            <StatBox label="סה״כ ימי־עבודה, קבלנים" value={report.totalSub} />
            <StatBox
              label="ממוצע עובדים ליום"
              value={report.avgPerDay ? report.avgPerDay.toFixed(1) : "0"}
            />
          </div>

          {report.days.length > 0 && (
            <ReportSection title="נוכחות ושעות עבודה לפי תאריך">
              <table style={styles.table}>
                <thead>
                  <tr>
                    <th style={styles.th}>תאריך</th>
                    <th style={styles.th}>עובדי משק</th>
                    <th style={styles.th}>קבלני משנה</th>
                    <th style={styles.th}>סה״כ עובדים</th>
                    <th style={styles.th}>שעות עבודה</th>
                    <th style={styles.th}>סה״כ שעות</th>
                  </tr>
                </thead>
                <tbody>
                  {report.days.map((day) => {
                    const ownWorkers = Number(day.ownWorkers) || 0;
                    const subs = (day.subcontractors || []).filter(
                      (s) => (Number(s.count) || 0) > 0
                    );
                    const subTotal = subs.reduce((sum, s) => sum + (Number(s.count) || 0), 0);
                    const hours = calcWorkHours(day.workStart, day.workEnd);
                    return (
                      <tr key={day.date}>
                        <td style={styles.td}>{fmtDateShort(parseDateKey(day.date))}</td>
                        <td style={styles.td}>{ownWorkers}</td>
                        <td style={styles.td}>
                          {subs.length
                            ? subs
                                .map((s) => `${s.name || "קבלן ללא שם"} (${s.count || 0})`)
                                .join(", ")
                            : "-"}
                        </td>
                        <td style={styles.td}>{ownWorkers + subTotal}</td>
                        <td style={styles.td}>
                          {day.workStart || "-"} עד {day.workEnd || "-"}
                        </td>
                        <td style={styles.td}>{hours !== null ? hours.toFixed(1) : "-"}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </ReportSection>
          )}

          {Object.keys(report.subTotals).length > 0 && (
            <ReportSection title="קבלני משנה — סה״כ ימי־עבודה">
              <table style={styles.table}>
                <thead>
                  <tr>
                    <th style={styles.th}>קבלן</th>
                    <th style={styles.th}>מספר ימים</th>
                    <th style={styles.th}>סה״כ עובדים</th>
                  </tr>
                </thead>
                <tbody>
                  {Object.entries(report.subTotals).map(([name, count]) => (
                    <tr key={name}>
                      <td style={styles.td}>{name}</td>
                      <td style={styles.td}>{report.subDaysCounts[name] || 0}</td>
                      <td style={styles.td}>{count}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </ReportSection>
          )}

          {report.taskList.length > 0 && (
            <ReportSection title="משימות שבוצעו">
              <table style={styles.table}>
                <thead>
                  <tr>
                    <th style={styles.th}>תאריך</th>
                    <th style={styles.th}>תיאור</th>
                    <th style={styles.th}>חלקה</th>
                    <th style={styles.th}>מנהרה</th>
                    <th style={styles.th}>הערות</th>
                  </tr>
                </thead>
                <tbody>
                  {report.taskList.map((t, i) => (
                    <tr key={i}>
                      <td style={styles.td}>{fmtDateShort(parseDateKey(t.date))}</td>
                      <td style={styles.td}>{t.description}</td>
                      <td style={styles.td}>{t.plot}</td>
                      <td style={styles.td}>{t.tunnel}</td>
                      <td style={styles.td}>{t.notes}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </ReportSection>
          )}

          {(Object.keys(report.plotCounts).length > 0 ||
            Object.keys(report.tunnelCounts).length > 0) && (
            <ReportSection title="פילוח לפי חלקה / מנהרה">
              <div className="grid-2">
                <div>
                  <div style={styles.subDivider}>לפי חלקה</div>
                  {Object.entries(report.plotCounts).map(([plot, count]) => (
                    <div key={plot} style={styles.tallyRow}>
                      <span>{plot}</span>
                      <span>{count}</span>
                    </div>
                  ))}
                </div>
                <div>
                  <div style={styles.subDivider}>לפי מנהרה</div>
                  {Object.entries(report.tunnelCounts).map(([tunnel, count]) => (
                    <div key={tunnel} style={styles.tallyRow}>
                      <span>{tunnel}</span>
                      <span>{count}</span>
                    </div>
                  ))}
                </div>
              </div>
            </ReportSection>
          )}

          {report.irrigationEntries.length > 0 && (
            <ReportSection title="הערות השקייה">
              {report.irrigationEntries.map((e, i) => (
                <div key={i} style={styles.noteEntry}>
                  <span style={styles.noteDate}>{fmtDateShort(parseDateKey(e.date))}</span>
                  <span>{e.text}</span>
                </div>
              ))}
            </ReportSection>
          )}

          {report.generalEntries.length > 0 && (
            <ReportSection title="הערות כלליות">
              {report.generalEntries.map((e, i) => (
                <div key={i} style={{ padding: "6px 0", borderBottom: "1px dashed #E7E4DB" }}>
                  <div style={styles.noteEntry}>
                    <span style={styles.noteDate}>{fmtDateShort(parseDateKey(e.date))}</span>
                    <span>{e.text}</span>
                  </div>
                  {(e.photos || []).length > 0 && (
                    <div style={styles.photoGrid}>
                      {e.photos.map((src, pi) => (
                        <img
                          key={pi}
                          src={src}
                          alt={`תמונה ${pi + 1}`}
                          style={styles.photoThumb}
                        />
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </ReportSection>
          )}

          {report.daysCount === 0 && (
            <div style={styles.emptyState}>אין נתונים בטווח התאריכים שנבחר</div>
          )}
        </div>
      )}
    </div>
  );
}

function ReportSection({ title, children }) {
  return (
    <div style={styles.reportSection}>
      <div style={styles.reportSectionTitle}>{title}</div>
      {children}
    </div>
  );
}

function StatBox({ label, value }) {
  return (
    <div style={styles.statBox}>
      <div style={styles.statValue}>{value}</div>
      <div style={styles.statLabel}>{label}</div>
    </div>
  );
}

function GlobalStyle() {
  return (
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;500;600;700;800;900&display=swap');
      * { box-sizing: border-box; }
      body { margin: 0; }
      .farm-scope { font-family: 'Heebo', sans-serif; direction: rtl; }
      .farm-scope input, .farm-scope select, .farm-scope button, .farm-scope textarea {
        font-family: 'Heebo', sans-serif;
      }
      .farm-scope .grid-2 {
        display: grid;
        grid-template-columns: 1fr;
        gap: 14px;
        margin-bottom: 14px;
      }
      @media (min-width: 640px) {
        .farm-scope .grid-2 { grid-template-columns: 1fr 1fr; }
      }
      .farm-scope input:focus, .farm-scope select:focus, .farm-scope textarea:focus {
        outline: 2px solid #E0A824;
        outline-offset: 1px;
      }
      .farm-scope button { cursor: pointer; }
      @media print {
        .no-print { display: none !important; }
        body { background: white !important; }
      }
      @media (prefers-reduced-motion: reduce) {
        .farm-scope * { transition: none !important; }
      }
    `}</style>
  );
}

